public class InnerJobRunMonitoringConfigurationFactory(Action<Humidifier.EMRContainers.JobRunTypes.MonitoringConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.JobRunTypes.MonitoringConfiguration>
{

    internal InnerJobRunS3MonitoringConfigurationFactory S3MonitoringConfigurationFactory { get; set; }

    internal InnerJobRunContainerLogRotationConfigurationFactory ContainerLogRotationConfigurationFactory { get; set; }

    internal InnerJobRunCloudWatchMonitoringConfigurationFactory CloudWatchMonitoringConfigurationFactory { get; set; }

    internal InnerJobRunManagedLogsFactory ManagedLogsFactory { get; set; }

    protected override Humidifier.EMRContainers.JobRunTypes.MonitoringConfiguration Create()
    {
        var monitoringConfigurationResult = CreateMonitoringConfiguration();
        factoryAction?.Invoke(monitoringConfigurationResult);

        return monitoringConfigurationResult;
    }

    private Humidifier.EMRContainers.JobRunTypes.MonitoringConfiguration CreateMonitoringConfiguration()
    {
        var monitoringConfigurationResult = new Humidifier.EMRContainers.JobRunTypes.MonitoringConfiguration();

        return monitoringConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.JobRunTypes.MonitoringConfiguration result)
    {
        base.CreateChildren(result);

        result.S3MonitoringConfiguration ??= S3MonitoringConfigurationFactory?.Build();
        result.ContainerLogRotationConfiguration ??= ContainerLogRotationConfigurationFactory?.Build();
        result.CloudWatchMonitoringConfiguration ??= CloudWatchMonitoringConfigurationFactory?.Build();
        result.ManagedLogs ??= ManagedLogsFactory?.Build();
    }

} // End Of Class

